targets.expr:
(
    (
        max by (instance) (
            node_network_info{operstate="up", device=~"(en|eth).*", address!~"00:15:5d:.*"}
            unless on (instance, address) wsl_wifi_adapter
        )
        or (max by (instance) (node_network_info) * 0)
    ) * 2
)
+
(
    max by (instance) (node_network_info{operstate="up", device=~"wl.*"})
    or max by (instance) (wsl_wifi_connected)
    or (max by (instance) (node_network_info) * 0)
)
